using System;using System.Linq;using BeamScheduleFormatter;
class RowHistoryTests {
 static int checks;static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}
 static void Main(){var history=new UndoHistory<int>(3);int value=0;Check(!history.CanUndo&&!history.CanRedo,"Empty history");foreach(int step in new[]{1,2,3,4})history.Record(step);history.Undo(n=>value=n);Check(value==4&&history.CanRedo,"Newest action undone");history.Undo(n=>value=n);Check(value==3,"Reverse order");history.Redo(n=>value=n);Check(value==3,"Redo restores next action");history.Record(5);Check(!history.CanRedo,"New edit invalidates redo");bool rejected=false;try{history.Undo(n=>{throw new Exception("write refused");});}catch{rejected=true;}Check(rejected&&history.NextUndo==5,"Failed apply retains history");history.Record(15);history.LimitCost(n=>n,2);Check(history.NextUndo==15,"History keeps most recent oversized transaction");history.Undo(n=>value=n);Check(!history.CanUndo,"Memory budget discards older snapshots");history.Clear();Check(!history.CanUndo&&!history.CanRedo,"New project clears history");foreach(int step in new[]{1,2,3,4})history.Record(step);int count=0;while(history.CanUndo)history.Undo(n=>count++);Check(count==3,"History bounded");
 foreach(var entry in new[]{new{Input="16",Display="Ø16 mm"},new{Input="Ø16 mm",Display="Ø16 mm"},new{Input="12.5",Display="Ø12.5 mm"}})Check(RebarDiameterText.Format(entry.Input)==entry.Display,"Diameter display "+entry.Input);Check(RebarDiameterText.Raw("Ø16 mm")=="16","Symbol stripped before numeric storage");Check(RebarDiameterText.Format(0)=="0","Unused bar group remains zero");Check(RebarDiameterText.Format("")=="","Blank remains blank");Check(RebarDiameterText.IsColumn(new[]{"Cover mm","Vertical dia mm","Rebar layers"},1),"RC wall diameter identified");Check(RebarDiameterText.IsColumn(new[]{"Grade","Dia","BUY kg"},1),"Rebar grade summary diameter identified");Check(!RebarDiameterText.IsColumn(new[]{"Tree ID","Measured diameter mm"},1),"Tree diameter not mistaken for rebar");Check(!RebarDiameterText.IsColumn(new[]{"ID","Grade","Diameter mm","Shaft weight kg"},2),"Bolt diameter not mistaken for rebar");Check(!RebarDiameterText.IsColumn(new[]{"Length","Thickness mm"},1),"Plate/wall thickness unchanged");Console.WriteLine("PASS: "+checks+" undo/redo lifecycle and rebar display/storage checks");}
}
